std::vector<long long> moveZeroes(std::vector<long long> nums) {
    std::vector<long long> out;
    for (std::size_t i = 0; i < nums.size(); ++i) if (nums[i] != 0) out.push_back(nums[i]);
    while (out.size() < nums.size()) out.push_back(0);
    return out;
}

